import React, { useRef, useEffect } from 'react';

export default function AuraCanvas({ hues = [200, 230], intensity = 0.6, speed = 0.5, style = {} }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const resize = () => { canvas.width = canvas.offsetWidth; canvas.height = canvas.offsetHeight; };
    resize();
    window.addEventListener('resize', resize);
    const ctx = canvas.getContext('2d');

    const draw = () => {
      t.current += 0.004 * speed;
      const W = canvas.width, H = canvas.height;
      ctx.clearRect(0, 0, W, H);

      const blobs = [
        { x: W*0.35 + Math.sin(t.current*0.4)*W*0.18, y: H*0.3  + Math.cos(t.current*0.3)*H*0.12, r: W*0.55, h: hues[0],   s: 55, l: 48, a: intensity*0.9 },
        { x: W*0.65 + Math.cos(t.current*0.35)*W*0.15,y: H*0.5  + Math.sin(t.current*0.28)*H*0.14, r: W*0.48, h: hues[1],   s: 50, l: 42, a: intensity*0.7 },
        { x: W*0.2  + Math.sin(t.current*0.25)*W*0.1, y: H*0.7  + Math.cos(t.current*0.32)*H*0.1,  r: W*0.40, h: hues[0]+20, s: 45, l: 52, a: intensity*0.5 },
        { x: W*0.75 + Math.cos(t.current*0.3)*W*0.08, y: H*0.2  + Math.sin(t.current*0.4)*H*0.08,  r: W*0.32, h: hues[1]+15, s: 48, l: 55, a: intensity*0.4 },
      ];

      blobs.forEach(b => {
        const g = ctx.createRadialGradient(b.x, b.y, 0, b.x, b.y, b.r);
        g.addColorStop(0,   `hsla(${b.h}, ${b.s}%, ${b.l}%, ${b.a})`);
        g.addColorStop(0.5, `hsla(${b.h}, ${b.s}%, ${b.l-5}%, ${b.a*0.4})`);
        g.addColorStop(1,   'transparent');
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, W, H);
      });

      // Vignette
      const vig = ctx.createRadialGradient(W/2, H/2, H*0.25, W/2, H/2, H*0.85);
      vig.addColorStop(0, 'transparent');
      vig.addColorStop(1, 'rgba(13,13,13,0.75)');
      ctx.fillStyle = vig;
      ctx.fillRect(0, 0, W, H);

      raf.current = requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(raf.current); window.removeEventListener('resize', resize); };
  }, [hues[0], hues[1], intensity, speed]);

  return <canvas ref={canvasRef} style={{ position:'absolute', inset:0, width:'100%', height:'100%', display:'block', ...style }} />;
}
